const idAlojamiento = $('Webhook').first().json.body.idAlojamiento;
const items = $input.all().map(i => i.json);
const fallo = items.find(j => j && j.error);
const fotos = items
  .filter(j => j && j.url)
  .sort((a, b) => (a.orden ?? 0) - (b.orden ?? 0));

if (fallo) {
  return [{ json: { idAlojamiento, sinFotos: true,
    motivo: 'Revisión no realizada: no se pudieron leer las fotografías.' } }];
}
if (fotos.length === 0) {
  return [{ json: { idAlojamiento, sinFotos: true,
    motivo: 'Revisión no realizada: el alojamiento no tiene fotografías.' } }];
}
return fotos.map((f, i) => ({ json: { idAlojamiento, orden: i + 1, url: f.url } }));

const GRAVES = ['O2', 'O3', 'O4', 'O6'];
const CATEGORIAS = {
  O1: 'odio, humillación o acoso',
  O2: 'violencia, daño o crueldad',
  O3: 'contenido sexual',
  O4: 'desnudos',
  O5: 'actividades delictivas',
  O6: 'armas o consumo de sustancias',
  O7: 'autolesiones',
  O8: 'crueldad animal',
  O9: 'desastres o emergencias'
};
const fotos = $('Dividir fotos').all().map(i => i.json);
const resultados = $('Evaluar foto').all().map(i => i.json);
const traducidas = $input.all().map(i => i.json);
const idAlojamiento = fotos[0].idAlojamiento;

// Traducción al español (nodo DeepL). Si falló, se conserva el texto original en inglés.
const traducir = (idx, original) => {
  const t = traducidas[idx] && traducidas[idx].text;
  return (typeof t === 'string' && t.trim()) ? t : original;
};

const corto = (t, n) => {
  const s = String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

// 1) Clasificar cada foto (se analizan TODAS, aunque alguna falle)
const detalle = fotos.map((f, idx) => {
  const r = resultados[idx] || {};
  const base = { orden: f.orden, url: f.url };
  if (r.statusCode === 200 && r.body) {
    const codigo = String(r.body.codigo || '').toUpperCase();
    const insegura = String(r.body.rating || '').toLowerCase() === 'unsafe';
    const tipo = !insegura ? 'segura' : (GRAVES.includes(codigo) ? 'grave' : 'leve');
    return { ...base, tipo, codigo, categoria: CATEGORIAS[codigo] || 'contenido no permitido', explicacion: traducir(idx, r.body.rationale) };
  }
  if (r.statusCode === 422) {
    const det = r.body && r.body.detail;
    return { ...base, tipo: 'inaccesible', explicacion: typeof det === 'string' ? det : JSON.stringify(det) };
  }
  const causa = r.statusCode ? 'HTTP ' + r.statusCode : ((r.error && r.error.message) || 'sin respuesta');
  return { ...base, tipo: 'error_tecnico', explicacion: causa };
});

// Descripción: primeras k frases de la explicación del modelo, con tope de caracteres
const frases = (t, k, max) => {
  const s = String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
  const lista = s.match(/[^.!?]+[.!?]+/g) || [s];
  let out = '';
  for (const fr of lista.slice(0, k)) {
    out += fr;
  }
  return corto(out.trim(), max);
};

// 2) Resumen corto: solo se nombran las fotos con problemas
const fotosDe = t => detalle.filter(d => d.tipo === t);
const nombres = t => fotosDe(t).map(d => d.orden).join(', ');
const nombresConCategoria = t => fotosDe(t)
  .map(d => 'foto ' + d.orden + (d.categoria ? ' (' + d.categoria + ')' : '')).join(', ');

// 3) Decisión por prioridad
const hay = t => fotosDe(t).length > 0;
const malas = detalle.filter(d => d.tipo === 'grave' || d.tipo === 'leve');
let estado, motivo;
if (hay('grave')) {
  estado = 'RECHAZADO';
  motivo = 'Rechazado: contenido no permitido en ' + nombresConCategoria('grave') + '.';
} else if (hay('inaccesible')) {
  estado = 'OBSERVADO';
  motivo = 'Observado: no se pudo abrir la(s) foto(s) ' + nombres('inaccesible') + '. Corregir las imágenes.';
} else if (hay('error_tecnico')) {
  estado = 'PENDIENTE';
  motivo = 'Revisión incompleta por error técnico en la(s) foto(s) ' + nombres('error_tecnico') + '. Reintentar.';
} else if (hay('leve')) {
  estado = 'OBSERVADO';
  motivo = 'Observado: contenido dudoso en ' + nombresConCategoria('leve') + '.';
} else {
  estado = 'PUBLICADO';
  motivo = 'Aprobado automáticamente: ' + detalle.length + (detalle.length === 1 ? ' foto revisada, sin problemas.' : ' fotos revisadas, sin problemas.');
}

// 4) Descripción de las fotos: detallada si hay algo malo, una frase si todo está bien
const lineasDesc = [];
if (malas.length > 0) {
  malas.forEach(d => lineasDesc.push('Foto ' + d.orden + ': ' + frases(d.explicacion, 2, 260)));
  const buenas = fotosDe('segura').map(d => d.orden);
  if (buenas.length > 0) lineasDesc.push('Sin problemas: foto(s) ' + buenas.join(', ') + '.');
} else if (estado === 'PUBLICADO') {
  detalle.forEach(d => lineasDesc.push('Foto ' + d.orden + ': ' + frases(d.explicacion, 1, 130)));
}
if (lineasDesc.length > 0) motivo = motivo + '\n' + lineasDesc.join('\n');

return [{ json: { idAlojamiento, estado, motivo, detalle } }];

const idAlojamiento = $('Webhook').first().json.body.idAlojamiento;
return [{ json: {
  idAlojamiento,
  estado: 'PENDIENTE',
  motivo: 'Revisión automática no disponible: el modelo no responde. Reintentar más tarde.'
} }];

const idAlojamiento = $('Webhook').first().json.body.idAlojamiento;
return [{ json: {
  idAlojamiento,
  estado: 'PENDIENTE',
  motivo: $json.motivo
} }];

// MODO_PRUEBA = true: todos los correos van a CORREO_PRUEBA (y se indica el destinatario real).
// Para enviar a los anfitriones reales, cambiar a false.
const MODO_PRUEBA = true;
const CORREO_PRUEBA = 'mostajolisa@gmail.com';
const REMITENTE = 'Aloja-Te Moderación <mostajolisa@gmail.com>';

const aloj = $('PATCH estado').first().json;
const usuario = $input.first().json || {};
const usuarioOk = !usuario.error && usuario.email;
const emailReal = usuarioOk ? usuario.email : null;
const nombre = (usuarioOk && usuario.nombre) ? usuario.nombre : (aloj.nombreAnfitrion || 'anfitrión');

if (!MODO_PRUEBA && !emailReal) return [];
const para = MODO_PRUEBA ? CORREO_PRUEBA : emailReal;

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const titulo = aloj.titulo || 'tu alojamiento';
const detalle = ($('Consolidar').first().json.detalle) || [];

const textos = {
  PUBLICADO: {
    asunto: '¡Tu alojamiento "' + titulo + '" ya está publicado!',
    insignia: 'PUBLICADO',
    encabezado: '¡Tu alojamiento ya está publicado!',
    cuerpo: 'Revisamos las fotografías de tu alojamiento y todo está en orden. Ya es visible para los huéspedes y puede recibir reservas.',
    pasos: ['Revisa que tus tarifas y disponibilidad estén al día.', 'Mantén tus fotografías actualizadas para generar más confianza.'],
    color: '#15803d', fondo: '#dcfce7'
  },
  RECHAZADO: {
    asunto: 'Tu alojamiento "' + titulo + '" no pudo ser publicado',
    insignia: 'RECHAZADO',
    encabezado: 'No pudimos publicar tu alojamiento',
    cuerpo: 'Al revisar las fotografías detectamos contenido que no está permitido en la plataforma, por lo que la publicación fue rechazada.',
    pasos: ['Revisa las fotografías marcadas más abajo.', 'Reemplázalas por imágenes que muestren únicamente tu alojamiento (habitaciones, espacios y entorno).', 'Registra nuevamente tu alojamiento con las fotografías corregidas.'],
    color: '#b91c1c', fondo: '#fee2e2'
  },
  OBSERVADO: {
    asunto: 'Tu alojamiento "' + titulo + '" necesita correcciones',
    insignia: 'CON OBSERVACIONES',
    encabezado: 'Tu alojamiento necesita correcciones',
    cuerpo: 'Revisamos tu alojamiento y encontramos observaciones en algunas fotografías. Aún no está publicado.',
    pasos: ['Corrige o reemplaza las fotografías marcadas más abajo.', 'Cuando estén listas, solicita una nueva revisión.'],
    color: '#b45309', fondo: '#fef3c7'
  }
};
const t = textos[aloj.estadoPublicacion];
if (!t) return [];

const estiloFoto = {
  segura: { icono: '&#10004;', texto: 'Sin problemas', color: '#15803d' },
  grave: { icono: '&#10006;', color: '#b91c1c' },
  leve: { icono: '&#9888;', color: '#b45309' },
  inaccesible: { icono: '&#9888;', texto: 'No pudimos abrir esta imagen (enlace roto o archivo no válido)', color: '#b45309' },
  error_tecnico: { icono: '&#9888;', texto: 'No se pudo analizar por un problema técnico temporal', color: '#b45309' }
};
const textoFoto = d => {
  const e = estiloFoto[d.tipo];
  if (d.tipo === 'grave') return 'Contenido no permitido: ' + (d.categoria || 'contenido no permitido');
  if (d.tipo === 'leve') return 'Contenido dudoso: ' + (d.categoria || 'por confirmar');
  return e.texto;
};
const filas = detalle.map(d => {
  const e = estiloFoto[d.tipo] || estiloFoto.error_tecnico;
  const miniatura = /^https?:/i.test(d.url || '')
    ? '<img src="' + esc(d.url) + '" width="84" height="64" alt="Foto ' + d.orden + '" style="object-fit:cover;border-radius:6px;display:block">'
    : '';
  return '<tr>' +
    '<td style="padding:8px;border-bottom:1px solid #e5e7eb;width:92px">' + miniatura + '</td>' +
    '<td style="padding:8px;border-bottom:1px solid #e5e7eb;font-size:14px">' +
      '<b>Foto ' + d.orden + '</b><br>' +
      '<span style="color:' + e.color + '">' + e.icono + ' ' + esc(textoFoto(d)) + '</span>' +
    '</td></tr>';
}).join('');

const pasos = t.pasos.map(p => '<li style="margin-bottom:4px">' + esc(p) + '</li>').join('');
const aviso = MODO_PRUEBA
  ? '<p style="background:#fef9c3;padding:8px 12px;border-radius:6px;font-size:13px;margin:0 0 16px">MODO PRUEBA: este correo habría sido enviado a <b>' +
    esc(emailReal || '(sin correo registrado)') + '</b>.</p>'
  : '';

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#1f2937;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden">' +
  '<div style="background:' + t.color + ';color:#ffffff;padding:16px 24px;font-size:18px;font-weight:bold">Aloja-Te</div>' +
  '<div style="padding:24px">' +
  aviso +
  '<span style="display:inline-block;background:' + t.fondo + ';color:' + t.color + ';font-size:12px;font-weight:bold;padding:4px 10px;border-radius:999px">' + esc(t.insignia) + '</span>' +
  '<h2 style="margin:12px 0 8px;color:' + t.color + '">' + esc(t.encabezado) + '</h2>' +
  '<p>Hola ' + esc(nombre) + ',</p>' +
  '<p>' + esc(t.cuerpo) + '</p>' +
  '<p style="background:#f3f4f6;padding:10px 14px;border-radius:6px"><b>Alojamiento:</b> ' + esc(titulo) + '</p>' +
  (filas ? '<h3 style="margin:20px 0 6px;font-size:15px">Resultado por fotografía</h3><table style="width:100%;border-collapse:collapse">' + filas + '</table>' : '') +
  '<h3 style="margin:20px 0 6px;font-size:15px">¿Qué sigue?</h3><ul style="padding-left:20px;font-size:14px">' + pasos + '</ul>' +
  '<p style="font-size:13px;color:#6b7280">Si crees que esta revisión automática se equivocó, responde a este correo o comunícate con el equipo de soporte de Aloja-Te.</p>' +
  '</div>' +
  '<div style="background:#f9fafb;padding:12px 24px;font-size:12px;color:#6b7280">Este es un mensaje automático de Aloja-Te sobre la revisión de fotografías de tu alojamiento.</div>' +
  '</div>';

return [{ json: { to: para, from: REMITENTE, subject: (MODO_PRUEBA ? '[PRUEBA] ' : '') + t.asunto, html } }];
